static u32 barr[131072];
static void *ptrs[8192];

static u32
cksum(void)
{
	u32 s = 0;
	int i;
	for(i = 0; i < 16384; i++)
		s += pat[i] ^ (u32)i;
	return s;
}

void
main(int argc, char **argv)
{
	int rounds = 300, i, bad = 0;
	Waitmsg *w;


	if(argc > 2 && strcmp(argv[1], "kid2") == 0){
		/* verify argv[2]: deterministic pattern */
		char *a = argv[2];
		int j, bad = 0;
		if((int)strlen(a) != 600){
			print("XTEST-ARGV-LEN %d want 600\n", (int)strlen(a));
			exits("argvlen");
		}
		for(j = 0; j < 600; j++){
			char want = 'a' + (j * 7 + j / 26) % 26;
			if(a[j] != want){
				if(bad < 3)
					print("XTEST-ARGV-BAD at %d got 0x%02x want 0x%02x\n", j, a[j] & 0xff, want);
				bad++;
			}
		}
		if(bad)
			exits("argv");
		exits(nil);
	}
	if(argc > 1 && strcmp(argv[1], "kid") == 0){
		u32 s = cksum();
		char *p;
		int j, nz = 0;
		if(s != 2563309568U){
			print("XTEST-RODATA-BAD cksum 0x%lux want 0x%lux\n", (ulong)s, (ulong)2563309568U);
			exits("rodata");
		}
		for(j = 0; j < 131072; j++)
			if(barr[j] != 0) nz++;
		if(nz){
			print("XTEST-BSS-NONZERO %d first at %d val 0x%lux\n", nz, 0, (ulong)0);
			for(j = 0; j < 131072; j++)
				if(barr[j] != 0){ print("XTEST-BSS-FIRST idx %d val 0x%lux addr %p\n", j, (ulong)barr[j], &barr[j]); break; }
			exits("bss");
		}
		for(j = 0; j < 8192; j++)
			if(ptrs[j] != nil) nz++;
		if(nz){
			print("XTEST-PTRS-NONZERO %d\n", nz);
			exits("ptrs");
		}
		p = sbrk(256 * 1024);
		if(p == (void*)-1)
			exits("sbrk");
		for(j = 0; j < 256 * 1024; j++)
			if(p[j] != 0) nz++;
		if(nz){
			print("XTEST-SBRK-NONZERO %d\n", nz);
			exits("sbrk");
		}
		exits(nil);
	}

	if(argc > 1 && strcmp(argv[1], "parent2") == 0){
		int rounds2 = 300, i2, bad2 = 0;
		static char pat2[601];
		for(i2 = 0; i2 < 600; i2++)
			pat2[i2] = 'a' + (i2 * 7 + i2 / 26) % 26;
		pat2[600] = 0;
		for(i2 = 0; i2 < rounds2; i2++){
			int pid = fork();
			if(pid == 0){
				char *a[] = { "test", "kid2", pat2, nil };
				exec("/bin/test", a);
				exits("exec");
			}
			w = wait();
			if(w == nil || w->msg[0] != '\0'){
				print("XTEST2 kid bad round %d msg '%s'\n", i2, w ? w->msg : "?");
				bad2++;
			}
			free(w);
		}
		print("XTEST2-DONE rounds %d bad %d\n", rounds2, bad2);
		exits(nil);
	}
	if(argc > 1)
		rounds = atoi(argv[1]);
	for(i = 0; i < rounds; i++){
		int pid = fork();
		if(pid == 0){
			char *a[] = { "test", "kid", nil };
			exec("/bin/test", a);
			print("XTEST exec fail round %d\n", i);
			exits("exec");
		}
		if(pid < 0)
			exits("fork");
		w = wait();
		if(w == nil || w->msg[0] != '\0'){
			print("XTEST kid bad round %d msg '%s'\n", i, w ? w->msg : "?");
			bad++;
		}
		free(w);
	}
	print("XTEST-DONE rounds %d bad %d\n", rounds, bad);
	exits(nil);
}
